sum (
  irate (
    container_cpu_usage_seconds_total{image!="",container!="POD", node=~"$node", namespace=~"$namespace", pod=~"$pod", container=~"$container"}[2m]
  )
) by (namespace,pod,container)
/
sum (
  container_spec_cpu_quota{image!="",container!="POD", node=~"$node", namespace=~"$namespace", pod=~"$pod", container=~"$container"}
) by (namespace,pod,container)
*
10000000

(
  sum (
    container_memory_working_set_bytes{container!="POD", node=~"$node", namespace=~"$namespace", pod=~"$pod", container=~"$container"}
  ) by (namespace,pod,container)
  /
  sum (
    container_spec_memory_limit_bytes{container!="POD",node=~"$node", namespace=~"$namespace", pod=~"$pod", container=~"$container"}
  ) by (namespace,pod,container)
) * 100

sum(
    avg(
      kube_pod_container_resource_requests{cluster="$cluster", namespace="$namespace", pod=~"$pod", resource="memory", container=~"$container"}
    ) by (container)
)

sum(
    avg(
      kube_pod_container_resource_limits{cluster="$cluster", namespace="$namespace", pod=~"$pod", resource="memory", container=~"$container"}
    ) by (container)
)

max(
max_over_time(vmauth_user_concurrent_requests_current{job=~"$job", instance=~"$instance", username=~"$user"}[$__rate_interval])
/ 
vmauth_user_concurrent_requests_capacity{job=~"$job", instance=~"$instance", username=~"$user"}
) by(username) > 0

1 - (

avg_over_time(
sum(sum(sum(container_memory_allocation_bytes{namespace=~"$namespace", container=~"$app.*"}) by (namespace,instance,container) * on(instance) group_left() (
				node_ram_hourly_cost{} / 1024 / 1024 / 1024
				+ on(node,instance_type) group_left()
					label_replace
					(
						kube_node_labels{}, "instance_type", "$1", "label_node_kubernetes_io_instance_type", "(.*)"
					) * 0
			) + sum(container_cpu_allocation{namespace=~"$namespace", container=~"$app.*"}) by (namespace,instance,container) * on(instance) group_left() (
	  			node_cpu_hourly_cost{} + on(node,instance_type) group_left()
		  			label_replace
		  			(
		  				kube_node_labels{}, "instance_type", "$1", "label_node_kubernetes_io_instance_type", "(.*)"
		  			) * 0
		  	)) by (container)) [1d:1h]
					)
/

avg_over_time(
sum(sum(sum(container_memory_allocation_bytes{namespace=~"$namespace", container=~"$app.*"}) by (namespace,instance,container) * on(instance) group_left() (
				node_ram_hourly_cost{} / 1024 / 1024 / 1024
				+ on(node,instance_type) group_left()
					label_replace
					(
						kube_node_labels{}, "instance_type", "$1", "label_node_kubernetes_io_instance_type", "(.*)"
					) * 0
			) + sum(container_cpu_allocation{namespace=~"$namespace", container=~"$app.*"}) by (namespace,instance,container) * on(instance) group_left() (
	  			node_cpu_hourly_cost{} + on(node,instance_type) group_left()
		  			label_replace
		  			(
		  				kube_node_labels{}, "instance_type", "$1", "label_node_kubernetes_io_instance_type", "(.*)"
		  			) * 0
		  	)) by (container)) [7d:1h]
					)
					)

sum(
 (
 (
 sum(kube_node_status_capacity_cpu_cores) by (node)
 * on (node) group_left (label_cloud_google_com_gke_preemptible)
 kube_node_labels{label_cloud_google_com_gke_preemptible="true"}
 ) * $costpcpu
 )
 or
 (
 (
 sum(kube_node_status_capacity_cpu_cores) by (node)
 * on (node) group_left (label_cloud_google_com_gke_preemptible)
 kube_node_labels{label_cloud_google_com_gke_preemptible!="true"}
 ) * ($costcpu - ($costcpu / 100 * $costDiscount))
 )
)

