        container_memory_usage_bytes{namespace="$namespace", pod=~"$pod.*"}
    )
    * on (pod) group_left()
    (
        namespace_workload_pod:kube_pod_owner:relabel{namespace="$namespace", workload="$workload", workload_type="$workload_type"}
    )
) by (pod)

double_exponential_smoothing(
  avg( 
    sum by(http_route)(
      rate(
        http_server_request_duration_seconds_count{job="$job",http_route=~"$http_route"}[$rateinterval]
      )
    )
  )[$predictive_interval:] offset $predictive_offset,
  0.5,
  0.5
) * 0.5

(
  sum by(deployment_environment_name, service_namespace, service_name) (
    rate(
      http_server_request_duration_seconds_count{
        deployment_environment_name=~"$deployment_environment_name",
        service_namespace=~"$service_namespace",
        service_name="$service_name",
        http_response_status_code=~"5.."
      }[$__rate_interval]
    )
  ) * 100
)
/
(
  sum by(deployment_environment_name, service_namespace, service_name) (
    rate(
      http_server_request_duration_seconds_count{
        deployment_environment_name=~"$deployment_environment_name",
        service_namespace=~"$service_namespace",
        service_name="$service_name"
      }[$__rate_interval]
    )
  )
)
or
(
  0
  *
  sum by(deployment_environment_name, service_namespace, service_name) (
    rate(
      http_server_request_duration_seconds_count{
        deployment_environment_name=~"$deployment_environment_name",
        service_namespace=~"$service_namespace",
        service_name="$service_name"
      }[$__rate_interval]
    )
  )
)

(
  sum without (rpc_grpc_status_code, instance) (
    rate(
      rpc_server_duration_milliseconds_count{
        deployment_environment_name=~"$deployment_environment_name",
        service_namespace=~"$service_namespace",
        service_name="$service_name",
        rpc_grpc_status_code!="0"
      }[$__rate_interval]
    )
  ) * 100
)
/
(
  sum without (rpc_grpc_status_code, instance) (
    rate(
      rpc_server_duration_milliseconds_count{
        deployment_environment_name=~"$deployment_environment_name",
        service_namespace=~"$service_namespace",
        service_name="$service_name"
      }[$__rate_interval]
    )
  )
)
or 
(
    0
    *
    sum without (rpc_grpc_status_code, instance) (
    rate(
      rpc_server_duration_milliseconds_count{
        deployment_environment_name=~"$deployment_environment_name",
        service_namespace=~"$service_namespace",
        service_name="$service_name"
      }[$__rate_interval]
    )
  )
)

sum by (outbound_service) (
  label_join(
    rate(
      http_client_request_duration_seconds_count{
        deployment_environment_name=~"$deployment_environment_name",
        service_namespace=~"$service_namespace",
        service_name="$service_name"
      }[$__rate_interval]
    ),
    "outbound_service",
    " ",
    "server_address",
    "http_request_method",
    "url_template"
  )
)

histogram_quantile(
  0.99,
  sum by (le, outbound_service) (
    label_join(
      rate(
        http_client_request_duration_seconds_bucket{
          deployment_environment_name=~"$deployment_environment_name",
          service_namespace=~"$service_namespace",
          service_name="$service_name"
        }[5m]
      ),
      "outbound_service",
      " ",
      "server_address",
      "http_request_method",
      "url_template"
    )
  )
)

sum by (database) (
  label_join(
    rate(
      db_client_operation_duration_seconds_count{
        deployment_environment_name=~"$deployment_environment_name",
        service_namespace=~"$service_namespace",
        service_name="$service_name"
      }[$__rate_interval]
    ),
    "database",
    "/",
    "server_address",
    "db_namespace"
  )
)

histogram_quantile(
  0.99,
  sum by (le, database) (
    label_join(
      rate(
        db_client_operation_duration_seconds_bucket{
          deployment_environment_name=~"$deployment_environment_name",
          service_namespace=~"$service_namespace",
          service_name="$service_name"
        }[5m]
      ),
      "database",
      "/",
      "server_address",
      "db_namespace"
    )
  )
)

sum(
  (
    (
      sum(kube_node_status_capacity_cpu_cores) by (node)
       * on (node) group_left (label_cloud_google_com_gke_preemptible)
      kube_node_labels{label_cloud_google_com_gke_preemptible="true"}
    ) * $costpcpu
  )
  or
  (
    (
      sum(kube_node_status_capacity_cpu_cores) by (node)
       * on (node) group_left (label_cloud_google_com_gke_preemptible)
      kube_node_labels{label_cloud_google_com_gke_preemptible!="true"}
    ) * ($costcpu - ($costcpu / 100 * $costDiscount))
  )
)

sum(
  (
    (
      sum(kube_node_status_capacity_memory_bytes) by (node)
       * on (node) group_left (label_cloud_google_com_gke_preemptible)
      kube_node_labels{label_cloud_google_com_gke_preemptible="true"}
    ) /1024/1024/1024 * $costpram
  )
  or
  (
    (
      sum(kube_node_status_capacity_memory_bytes) by (node)
       * on (node) group_left (label_cloud_google_com_gke_preemptible)
      kube_node_labels{label_cloud_google_com_gke_preemptible!="true"}
    ) /1024/1024/1024 * ($costram - ($costram / 100 * $costDiscount))
)
)

# CPU
sum(
  (
    (
      sum(kube_node_status_capacity_cpu_cores) by (node)
       * on (node) group_left (label_cloud_google_com_gke_preemptible)
      kube_node_labels{label_cloud_google_com_gke_preemptible="true"}
    ) * $costpcpu
  )
  or
  (
    (
      sum(kube_node_status_capacity_cpu_cores) by (node)
       * on (node) group_left (label_cloud_google_com_gke_preemptible)
      kube_node_labels{label_cloud_google_com_gke_preemptible!="true"}
    ) * ($costcpu - ($costcpu / 100 * $costDiscount))
  )
) 

+ 

# Storage
sum (
  sum(kube_persistentvolumeclaim_info{storageclass=~".*ssd.*"}) by (persistentvolumeclaim, namespace, storageclass)
  + on (persistentvolumeclaim, namespace) group_right(storageclass)
  sum(kube_persistentvolumeclaim_resource_requests_storage_bytes) by (persistentvolumeclaim, namespace)
) / 1024 / 1024 /1024 * $costStorageSSD

+

sum (
  sum(kube_persistentvolumeclaim_info{storageclass!~".*ssd.*"}) by (persistentvolumeclaim, namespace, storageclass)
  + on (persistentvolumeclaim, namespace) group_right(storageclass)
  sum(kube_persistentvolumeclaim_resource_requests_storage_bytes) by (persistentvolumeclaim, namespace)
) / 1024 / 1024 /1024 * $costStorageStandard

+ 

sum(container_fs_limit_bytes{device=~"^/dev/[sv]d[a-z][1-9]$",id="/"}) / 1024 / 1024 / 1024 * $costStorageStandard

+ 
# RAM
sum(
  (
    (
      sum(kube_node_status_capacity_memory_bytes) by (node)
       * on (node) group_left (label_cloud_google_com_gke_preemptible)
      kube_node_labels{label_cloud_google_com_gke_preemptible="true"}
    ) /1024/1024/1024 * $costpram
  )
  or
  (
    (
      sum(kube_node_status_capacity_memory_bytes) by (node)
       * on (node) group_left (label_cloud_google_com_gke_preemptible)
      kube_node_labels{label_cloud_google_com_gke_preemptible!="true"}
    ) /1024/1024/1024 * ($costram - ($costram / 100 * $costDiscount))
)
)

(
  kubelet_volume_stats_capacity_bytes{cluster="$cluster", job="kubelet", metrics_path="/metrics", namespace="$namespace", persistentvolumeclaim="$volume"}
  -
  kubelet_volume_stats_available_bytes{cluster="$cluster", job="kubelet", metrics_path="/metrics", namespace="$namespace", persistentvolumeclaim="$volume"}
)
/
kubelet_volume_stats_capacity_bytes{cluster="$cluster", job="kubelet", metrics_path="/metrics", namespace="$namespace", persistentvolumeclaim="$volume"}
* 100

kubelet_volume_stats_inodes_used{cluster="$cluster", job="kubelet", metrics_path="/metrics", namespace="$namespace", persistentvolumeclaim="$volume"}
/
kubelet_volume_stats_inodes{cluster="$cluster", job="kubelet", metrics_path="/metrics", namespace="$namespace", persistentvolumeclaim="$volume"}
* 100

sum(
  max by (device) (
    node_filesystem_size_bytes{job="node-exporter", instance="$instance", fstype!=""}
  -
    node_filesystem_avail_bytes{job="node-exporter", instance="$instance", fstype!=""}
  )
)

sum by (instance) (
    (
      node_filesystem_size_bytes{job="node-exporter", instance=~"$hosts", mountpoint="/data"} 
      - 
      node_filesystem_avail_bytes{job="node-exporter", instance=~"$hosts", mountpoint="/data"}
    ) 
    / 
    node_filesystem_size_bytes{job="node-exporter", instance=~"$hosts", mountpoint="/data"}
 )

sum without (device) (
  max without (fstype, mountpoint) (
    node_filesystem_size_bytes{job="node", fstype!=""} - node_filesystem_avail_bytes{job="node", fstype!=""}
  )
) 
/ scalar(sum(max without (fstype, mountpoint) (node_filesystem_size_bytes{job="node", fstype!=""})))
